"""The service's settings, from environment variables with defaults."""

from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

PACKAGE_DIR = Path(__file__).parent

# The committed station list (generated by select_stations.py).
STATIONS_CSV = PACKAGE_DIR / "stations.csv"


@dataclass(frozen=True)
class Config:
    """Where the service keeps its data, and the code it runs."""

    data_dir: Path
    stations_csv: Path
    # The commit the image was built from, for the results' provenance.
    code_commit: str

    @property
    def database(self) -> Path:
        """Return the SQLite database's path."""
        return self.data_dir / "precip_eval.sqlite"

    @property
    def tmp_dir(self) -> Path:
        """Return the directory downloads are written to before they are read."""
        return self.data_dir / "tmp"

    @property
    def heartbeat(self) -> Path:
        """Return the file the scheduler touches on every turn (healthcheck)."""
        return self.data_dir / "heartbeat"

    @classmethod
    def from_env(cls) -> Config:
        """Return the settings from the environment."""
        return cls(
            data_dir=Path(os.environ.get("PRECIP_EVAL_DATA_DIR", "/data")),
            stations_csv=Path(os.environ.get("PRECIP_EVAL_STATIONS", STATIONS_CSV)),
            code_commit=os.environ.get("PRECIP_EVAL_COMMIT", "unknown"),
        )
